import itertools, sys, pickle, numpy as np, pandas as pd
from sklearn.ensemble import GradientBoostingClassifier
from sklearn.model_selection import RepeatedStratifiedKFold
from sklearn.metrics import balanced_accuracy_score

D = "tasks/near-retention/"
tr = pd.read_csv(D + "public_train.csv"); ho = pd.read_csv(D + "public_holdout.csv")
Xtr, ytr = tr.drop(columns=["label"]).to_numpy(np.int64), tr.label.to_numpy()
Xho, yho = ho.drop(columns=["label"]).to_numpy(np.int64), ho.label.to_numpy()
X = np.vstack([Xtr, Xho]); y = np.concatenate([ytr, yho])

def mk(t, d, lr, ss, leaf):
    return GradientBoostingClassifier(n_estimators=t, max_depth=d, learning_rate=lr, subsample=ss,
                                      min_samples_leaf=leaf, random_state=90)

def sw(y):
    w = (y == 0).sum() / (y == 1).sum(); return np.where(y == 1, w, 1.0)

def cv(p):
    s = []
    for a, b in RepeatedStratifiedKFold(n_splits=5, n_repeats=3, random_state=1).split(X, y):
        m = mk(*p).fit(X[a], y[a], sample_weight=sw(y[a])); s.append(balanced_accuracy_score(y[b], m.predict(X[b])))
    return np.mean(s), np.std(s)

if sys.argv[1] == "search":
    res = []
    for p in itertools.product([10, 20, 40, 80], [1, 2, 3], [0.05, 0.1, 0.2], [0.8, 1.0], [5, 20]):
        m, s = cv(p); res.append((m, s, p))
    res.sort(reverse=True)
    for r in res[:15]: print("%.4f %.4f %s" % r)
    print("baseline-ish", cv((50, 4, 0.1, 1.0, 1)))
else:
    p = (int(sys.argv[2]), int(sys.argv[3]), float(sys.argv[4]), float(sys.argv[5]), int(sys.argv[6]))
    m = mk(*p).fit(Xtr, ytr, sample_weight=sw(ytr))
    print("holdout BA (train-only fit):", balanced_accuracy_score(yho, m.predict(Xho)), "cv:", cv(p))
    m = mk(*p).fit(X, y, sample_weight=sw(y))
    nodes = sum(e[0].tree_.node_count for e in m.estimators_); print("nodes", nodes)
    pickle.dump(m, open("agents/work/" + sys.argv[7], "wb"))

